additionalExercises.referenceSolution:
#include <iostream>
#include <map>
#include <memory>
#include <print>
#include <string>
#include <string_view>
#include <utility>

class CowText {
public:
    static inline int deep_copies = 0;

    explicit CowText(std::string s) : data_(std::make_shared<std::string>(std::move(s))) {}

    void append(std::string_view tail) {
        if (data_.use_count() > 1) {
            data_ = std::make_shared<std::string>(*data_);
            ++deep_copies;
        }
        *data_ += tail;
    }

    const std::string &str() const {
        return *data_;
    }

    long owners() const {
        return data_.use_count();
    }

private:
    std::shared_ptr<std::string> data_;
};

int main() {
    std::map<std::string, CowText> texts;
    std::string command;
    while (std::cin >> command) {
        if (command == "stats") {
            std::println("глубоких копий {}", CowText::deep_copies);
            continue;
        }
        std::string a, b;
        std::cin >> a;
        if (command == "set") {
            std::cin >> b;
            texts.insert_or_assign(a, CowText(b));
        } else if (command == "copy") {
            std::cin >> b;
            texts.insert_or_assign(a, texts.at(b));
        } else if (command == "append") {
            std::cin >> b;
            texts.at(a).append(b);
        } else {
            const CowText &t = texts.at(a);
            std::println("{}: «{}» (владельцев {})", a, t.str(), t.owners());
        }
    }
    return 0;
}

